package com.bhagya.qa.performance;
import com.sun.net.httpserver.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;
public class DemoService { private HttpServer server; private int port; public void start() throws IOException { server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);port=server.getAddress().getPort();server.createContext("/health",e->reply(e,200,"{\"status\":\"UP\"}"));server.createContext("/api/products",e->{if(!"GET".equalsIgnoreCase(e.getRequestMethod()))reply(e,405,"{\"error\":\"method_not_allowed\"}");else reply(e,200,"{\"products\":[{\"id\":1,\"name\":\"Demo Product\"}],\"count\":1}");});server.createContext("/api/slow",e->{try{Thread.sleep(80);}catch(InterruptedException x){Thread.currentThread().interrupt();}reply(e,200,"{\"status\":\"slow-demo\"}");});server.setExecutor(Executors.newFixedThreadPool(16));server.start();} private void reply(HttpExchange e,int code,String body)throws IOException{byte[]b=body.getBytes(StandardCharsets.UTF_8);e.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");e.sendResponseHeaders(code,b.length);try(OutputStream o=e.getResponseBody()){o.write(b);}} public int getPort(){return port;}public void stop(){if(server!=null)server.stop(0);}}
